export interface RubricCriterion {
  id: string;
  label: string;
  description: string;
  score: number;
  maxScore: number;
  feedback: string;
}

/**
 * One line of the writer's rubric configuration.
 *
 * The spine — the criteria Twyne ships — stays fixed so a score means the same
 * thing from one pass to the next, and so the trend line is honest. What the
 * writer controls is the weighting, whether a spine criterion is shown at all,
 * and any number of criteria of their own that the room will judge alongside
 * them. Spine entries can be disabled and reweighted but never deleted; that
 * is what keeps two runs comparable.
 */
export interface RubricCriterionSpec {
  id: string;
  label: string;
  description: string;
  source: "spine" | "custom";
  enabled: boolean;
  /** Relative weight within the criteria list. 1 is the default. */
  weight: number;
}

/** The criteria Twyne ships. Order is the order they render in. */
export const SPINE_CRITERIA: ReadonlyArray<
  Pick<RubricCriterionSpec, "id" | "label" | "description">
> = [
  {
    id: "targetFit",
    label: "On brief",
    description:
      "Is the draft about what the brief asks, for the reader it names? Judged apart from how well it's written.",
  },
  {
    id: "thesis",
    label: "Argument",
    description:
      "Is the main point clear, and does the draft make the case for it?",
  },
  {
    id: "evidence",
    label: "Evidence",
    description:
      "Are the claims backed by sources, examples or figures that actually fit them?",
  },
  {
    id: "sufficiency",
    label: "Development",
    description: "Is there enough on-topic material to earn the main point?",
  },
  {
    id: "integrity",
    label: "Straight talk",
    description:
      "Free of padding, vague words, repetition and claims stated more strongly than shown.",
  },
  {
    id: "structure",
    label: "Structure",
    description:
      "Does each part follow from the last, with clear turns between them?",
  },
  {
    id: "pacing",
    label: "Rhythm",
    description: "Do sentence lengths vary enough to keep the reader moving?",
  },
  {
    id: "voice",
    label: "Voice",
    description:
      "Does it sound like one writer, pitched at the reader the brief names?",
  },
  {
    id: "vocabulary",
    label: "Word choice",
    description:
      "Precise, varied words rather than repeats, abstractions and jargon.",
  },
  {
    id: "paragraph",
    label: "Paragraphs",
    description:
      "A readable mix of short and long paragraphs, each doing one job.",
  },
  {
    id: "engagement",
    label: "Reader pull",
    description:
      "Would the reader stay to the end? Follows the overall grade rather than being marked on its own.",
  },
] as const;

/** One recorded rubric pass, for the trend line. */
export interface RubricHistoryEntry {
  scoringMethod?: "judgement" | "room";
  /** Folio whose rubric run produced this point. */
  folioId?: string;
  at: number;
  overall: number;
  grade: string;
  targetFit?: number;
  perCriterion: Record<string, number>;
}

export interface RubricResult {
  judgementGrade?: import("../utils/rubric-grade").RubricGrade;
  draftFingerprint?: string;
  scoringMethod?: "judgement" | "room";
  /** Folio whose manuscript was graded. */
  folioId?: string;
  criteria: RubricCriterion[];
  overallScore: number;
  overallGrade: string;
  summary: string;
  timestamp: number;
  /** Per-persona judge scores, 0-10. */
  judges: import("../utils/rubric").JudgeResult[];
  /** Static-feature breakdown (length, pacing, evidence, …). */
  staticScore: import("../utils/rubric").StaticScore;
  /** Optional full-page narrative review, generated on demand. */
  review?: string;
  /** Provider tag for the narrative review. */
  reviewProvider?: string;
  /**
   * Relevance to the brief's audience and goal, 0-10, from the target-fit
   * judge. Caps the shape-derived criteria and scales the static weight in
   * the combined grade. Absent on results saved before the gate existed.
   */
  targetFit?: number;
  /**
   * The same criteria re-scored under the writer's own weights, 0-100. Shown
   * beside the editorial grade, never in place of it. Absent unless the
   * writer has customised their rubric.
   */
  writerScore?: number;
}

/** One editor's full-page memo on the whole document. */
export interface PersonaMemo {
  personaId: string;
  personaName: string;
  personaColor: string;
  text: string;

