    <div class="flex h-full min-h-0 flex-col overflow-y-auto bg-[var(--color-paper-2)]">
      {/* ── Header ─────────────────────────────────────────── */}
      <div class="border-b border-[var(--color-paper-3)] bg-[var(--color-paper-soft)] px-4 py-3">
